function readCredit(text){let compact=text.replace(/\s+/g,' '),scoreMatch=compact.match(/(?:cibil\s*(?:transunion\s*)?score|credit score|bureau score|experian score|equifax score|crif(?: high mark)? score)\D{0,45}([3-8]\d{2}|900)\b/i);let fields={};for(let [key,re]of [['Total accounts',/(?:total (?:number of )?accounts|accounts\s+total)\D{0,12}(\d{1,3})/i],['Active accounts',/(?:active (?:number of )?accounts|open accounts)\D{0,12}(\d{1,3})/i],['Closed accounts',/closed accounts\D{0,12}(\d{1,3})/i],['Overdue amount',/(?:total overdue|overdue amount|amount overdue)\D{0,12}([\d,]+(?:\.\d{2})?)/i],['Current balance',/(?:total current balance|current balance)\D{0,12}([\d,]+(?:\.\d{2})?)/i],['Credit enquiries',/(?:total (?:number of )?(?:enquiries|inquiries))\D{0,12}(\d{1,3})/i]])fields[key]=compact.match(re)?.[1]??null;let signals=[];for(let [re,label]of [[/written[ -]?off/i,'Written-off wording detected.'],[/settled|settlement/i,'Settlement wording detected.'],[/\b(?:030|060|090|120|150|180|360|SUB|DBT|LSS)\b/,'Possible delinquency / DPD codes detected.'],[/overdue/i,'Overdue wording detected.']])if(re.test(text))signals.push(label);return{score:scoreMatch?+scoreMatch[1]:null,bureau:/cibil|transunion/i.test(text)?'TransUnion CIBIL':/experian/i.test(text)?'Experian':/equifax/i.test(text)?'Equifax':/crif/i.test(text)?'CRIF High Mark':'Bureau not identified',fields,signals,text,chars:text.length}}

const val=v=>v===null||v===undefined||v===''?'Not reported':esc(v),amt=v=>v===null||v===undefined?'—':money(v);
function reportBar(){return `<div class="report-bar"><div class="row"><span class="file-icon">▤</span><div><b>${esc(creditName||'No report uploaded')}</b><p>${credit?`${esc(credit.bureau)} &nbsp; · &nbsp; ${credit.pages} pages &nbsp; · &nbsp; ${esc(credit.customer.reportDate||'Date not located')}`:'Upload a report to begin your analysis'}</p></div>${demo?'<span class="tag lavender">DEMO DATA</span>':''}</div><div class="row">${reports.length>1?`<select id="reportSelect" aria-label="Choose report">${reports.map((r,i)=>`<option value="${i}" ${r===credit?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`:''}<button class="quiet" id="clearReports" ${credit?'':'disabled'}>Clear</button><button class="secondary" id="exportAnalysis" ${credit?'':'disabled'}>↓ Export analysis</button></div></div>`}
function scoreCard(){let selected=credit?.scores[0],score=selected?.value;return `<div class="card score-card"><div class="row"><h2>Credit score</h2><span class="mini">${esc(credit?.bureau||'Awaiting report')}</span></div><div class="gauge"><svg viewBox="0 0 260 145" aria-hidden="true"><defs><linearGradient id="scoreGradient"><stop stop-color="#e7b675"/><stop offset=".45" stop-color="#b191dc"/><stop offset="1" stop-color="#4aa9a2"/></linearGradient></defs><path d="M25 125 A105 105 0 0 1 235 125" fill="none" stroke="var(--border)" stroke-width="15" stroke-linecap="round"/><path d="M25 125 A105 105 0 0 1 235 125" fill="none" stroke="url(#scoreGradient)" stroke-width="15" stroke-linecap="round" stroke-dasharray="${score?(score-300)/600*330:0} 330"/></svg><div class="score-value">${score??'—'}<span>OUT OF 900</span></div><div class="gauge-labels"><span>300</span><span>900</span></div></div><div class="score-description"><span class="tag lavender">${esc(selected?.label||'Awaiting report')}</span><p>${credit?.scores.length>1?credit.scores.slice(1).map(s=>`${esc(s.label)}: <b>${s.value}</b>`).join(' · '):'A clearer picture starts with the details.'}</p></div></div>`}
function metrics(){let t=credit?.totals,a=credit?.accounts;return `<div class="credit-metrics">${stat('Total outstanding',credit?amt(credit.summary.reportedBalance??t.balance):'—',credit?(credit.summary.reportedBalance!==null?'Report summary balance':`Across ${a.length} extracted accounts`):'Upload a report','▣')}${stat('Total overdue',credit?amt(credit.summary.reportedOverdue??t.overdue):'—',credit?`${a.filter(x=>x.overdue>0).length} accounts with extracted overdue amounts`:'Review payment obligations','△')}${stat('Credit accounts',credit?a.length:'—',credit?`${t.active} active · ${t.closed} closed`:'Loans and credit cards','▦')}${stat('Card utilization',t?.util!=null?t.util.toFixed(1)+'%':'—',t?.util!=null?'Known card balances ÷ reported card limits':'Requires reported card credit limits','▱')}</div>`}
function customerCard(){if(!credit)return'';let c=credit.customer;return `<details class="card customer"><summary>Borrower details <span class="mini">Personal data is masked where appropriate</span></summary><div class="detail-grid">${Object.entries({'Name':c.name,'Date of birth':c.dob,'PAN':c.pan,'Phone':c.phone,'Email':c.email,'Report date':c.reportDate,'Secured accounts':credit.totals.secured,'Other accounts':credit.totals.unsecured}).map(([k,v])=>`<div><small>${k}</small><b>${val(v)}</b></div>`).join('')}</div></details>`}
function accountTable(){let a=credit?.accounts||[];return `<div class="card account-panel"><div class="row section-title"><div><h2>Credit accounts <span class="count">${a.length}</span></h2><p>A closer look at your loans and credit cards.</p></div><div class="table-tools"><input id="accountSearch" class="search" placeholder="Search accounts" aria-label="Search credit accounts"><select id="accountFilter" aria-label="Filter accounts"><option value="all">All accounts</option><option value="flagged">Flagged accounts</option><option value="active">Active accounts</option><option value="closed">Closed accounts</option></select></div></div><div class="table-wrap"><table><thead><tr><th>LENDER / ACCOUNT</th><th>OUTSTANDING</th><th>OVERDUE</th><th>STATUS</th><th>REVIEW</th><th></th></tr></thead><tbody id="accountsBody"></tbody></table></div><div class="table-footer"><span id="accountCount">${a.length} extracted accounts</span><span>Click an account for full details and source text</span></div></div>`}
function accountRows(){let q=$('#accountSearch')?.value.toLowerCase()||'',f=$('#accountFilter')?.value||'all',a=(credit?.accounts||[]).filter(a=>`${a.lender} ${a.type} ${a.masked}`.toLowerCase().includes(q)&&(f==='all'||f==='flagged'&&a.flags.length||f==='active'&&a.active||f==='closed'&&/closed|inactive/i.test(a.status)));$('#accountsBody').innerHTML=a.map(a=>`<tr><td><div class="lender"><span class="bank-icon bank-${a.id%4}">${esc((a.lender||'?')[0])}</span><div><b>${esc(a.lender||'Lender not disclosed')}</b><small>${esc(a.type||'Account type not found')} · ${esc(a.masked||'Number not disclosed')}</small></div></div></td><td>${amt(a.balance)}</td><td class="${a.overdue>0?'negative':''}">${amt(a.overdue)}</td><td><span class="tag ${a.active?'':'lavender'}">${esc(a.status)}</span></td><td>${a.flags.length?a.flags.map(f=>`<span class="flag">● ${esc(f)}</span>`).join('<br>'):'<span class="mini">No extracted flags</span>'}</td><td><button class="quiet" data-account="${a.id}" aria-label="View account ${a.id}">↗</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">${credit?'No accounts match your filter.':'Upload a report or explore sample data to view credit accounts.'}</td></tr>`;$('#accountCount').textContent=`Showing ${a.length} of ${credit?.accounts.length||0} accounts`;document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>showAccount(+b.dataset.account))}
function historyPanel(full=false){let a=credit?.accounts||[],all=[...new Set(a.flatMap(a=>a.history.filter(h=>h.status!=='unknown').map(h=>h.month)))].sort().reverse(),latest=all[0],periods=[];if(latest){let d=new Date(latest+'-01T12:00:00');for(let i=0;i<(full?36:12);i++){periods.unshift(d.toISOString().slice(0,7));d.setMonth(d.getMonth()-1)}}return `<div class="card history-panel"><div class="row section-title"><div><h2>Payment history</h2><p>${full?'A 36-month view. Open an account to see its full extracted history.':'A 12-month view of reported payment history.'}</p></div><div class="legend"><span>🟢 On time</span><span>🟣 Standard</span><span>🟠 Late</span><span>⚪ Unreported</span></div></div><div class="table-wrap"><table class="history-table"><thead><tr><th>ACCOUNT</th>${periods.map(m=>`<th>${new Date(m+'-01T12:00:00').toLocaleDateString('en-IN',{month:'short',year:'2-digit'})}</th>`).join('')}</tr></thead><tbody>${a.map(a=>`<tr><td><button class="quiet history-account" data-history="${a.id}">${esc(a.lender||'Not disclosed')}<small>${esc(a.masked||'Account '+a.id)}</small></button></td>${periods.map(m=>{let h=a.history.find(h=>h.month===m);return `<td><span class="dpd ${h?.status||'unknown'}" title="${m}: ${esc(h?.code||'Not reported')}">${esc(h?.code??'–')}</span></td>`}).join('')}</tr>`).join('')||'<tr><td class="empty">No payment history loaded.</td></tr>'}</tbody></table></div><div class="table-footer">STD / S means standard asset classification, not proof of zero days overdue. Missing months are never treated as on-time payments.</div></div>`}
function inquiriesPanel(){let a=credit?.enquiries||[];return `<div class="card account-panel"><div class="row section-title"><div><h2>Credit inquiries <span class="count">${a.length}</span></h2><p>Extracted inquiry records; repeated dates may represent separate applications.</p></div><button id="exportInquiries" class="secondary">↓ Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>LENDER</th><th>ENQUIRY DATE</th><th>PURPOSE</th><th>AMOUNT</th></tr></thead><tbody>${a.map(e=>`<tr><td>${val(e.lender)}</td><td>${val(e.date)}</td><td>${val(e.purpose)}</td><td>${amt(e.amount)}</td></tr>`).join('')||`<tr><td colspan="4" class="empty">${credit?.kind==='experian'?'The report states no inquiry records found.':credit?.summary.reportedEnquiries===0?'The report summary states zero inquiries.':'No inquiry rows were extracted. Check the original report for completeness.'}</td></tr>`}</tbody></table></div></div>`}
function insightsPanel(){let a=(credit?.accounts||[]).filter(a=>a.flags.length);return `<div class="card"><h2>Issues & insights</h2><p>These are reported facts and review prompts, not a lending recommendation.</p>${credit?.warnings.map(w=>`<div class="notice">${esc(w)}</div>`).join('')||''}${a.map(a=>`<button class="insight-item" data-insight="${a.id}"><span class="bank-icon bank-${a.id%4}">${a.id}</span><div><b>${esc(a.lender||'Lender not disclosed')} · ${esc(a.masked||'Account '+a.id)}</b><p>${esc(a.flags.join(' · '))} · Max numeric DPD ${a.maxDPD} · Overdue ${amt(a.overdue)}</p></div><span>↗</span></button>`).join('')||'<p class="empty">No account-level warning signals extracted. This does not certify a clean credit history.</p>'}</div>`}
function creditDashboard(view){let flags=credit?.accounts.filter(a=>a.flags.length).length||0;return reportBar()+(view==='overview'||view==='credit'?`<div class="credit-overview">${scoreCard()}${metrics()}</div><div class="insight-strip"><span class="insight-icon">✧</span><div><b>A little attention can make a big difference.</b><p>${credit?`${flags} accounts have items to review. Start with overdue balances and payment history.`:'Upload any number of report pages. We read text and scan image-only pages locally.'}</p></div><button class="quiet" data-go="insights">Review insights &nbsp; →</button></div>${credit?.warnings.length?`<div class="notice">${credit.warnings.map(esc).join('<br>')}</div>`:''}${customerCard()}${accountTable()}${historyPanel()}`:view==='accounts'?customerCard()+accountTable():view==='history'?historyPanel(true):view==='inquiries'?inquiriesPanel():insightsPanel())}
function bindCreditUI(){if($('#accountsBody')){accountRows();$('#accountSearch').oninput=accountRows;$('#accountFilter').onchange=accountRows}document.querySelectorAll('[data-history],[data-insight]').forEach(b=>b.onclick=()=>showAccount(+(b.dataset.history||b.dataset.insight)));if($('#reportSelect'))$('#reportSelect').onchange=e=>{credit=reports[+e.target.value];creditName=credit.name;demo=!!credit.demo;render()};if($('#exportAnalysis'))$('#exportAnalysis').onclick=exportAnalysis;if($('#clearReports'))$('#clearReports').onclick=()=>{reports=[];credit=null;creditName='';demo=false;reportFiles.forEach(o=>{if(o.url)URL.revokeObjectURL(o.url)});reportFiles.clear();render();toast('Reports cleared from this session.')};if($('#exportInquiries'))$('#exportInquiries').onclick=()=>download('credit-inquiries.csv',[['Lender','Date','Purpose','Amount'],...(credit?.enquiries||[]).map(e=>[e.lender,e.date,e.purpose,e.amount])])}
function exportAnalysis(){if(!credit)return;download('creditlens-credit-accounts.csv',[['Bureau','Score','Account','Lender','Type','Ownership','Opened','Closed','Reported','Sanctioned','High credit','Credit limit','Balance','Overdue','EMI / payment amount','Rate','Tenure','Last payment','Status','Written off','Settlement','Flags','Source page'],...credit.accounts.map(a=>[credit.bureau,credit.score,a.masked,a.lender,a.type,a.ownership,a.opened,a.closed,a.reported,a.sanctioned,a.highCredit,a.limit,a.balance,a.overdue,a.emi,a.rate,a.tenure,a.lastPayment,a.status,a.writtenOff,a.settlement,a.flags.join('; '),a.page])]);toast('Account analysis exported. Missing fields remain blank.')}
function showAccount(id){let a=credit.accounts.find(a=>a.id===id);if(!a)return;let d=$('#detailDialog');$('#detailContent').innerHTML=`<div class="row"><div><span class="eyebrow">ACCOUNT ${a.id} · SOURCE PAGE ${a.page}</span><h2>${esc(a.lender||'Lender not disclosed')}</h2><p>${esc(a.type||'Unknown account type')} · ${esc(a.masked||'Number not disclosed')}</p></div><button id="closeDetail" class="secondary">✕ Close</button></div><div class="detail-grid">${Object.entries({'Ownership':val(a.ownership),'Status':val(a.status),'Opened':val(a.opened),'Closed':val(a.closed),'Reported':val(a.reported),'Sanctioned amount':amt(a.sanctioned),'High credit':amt(a.highCredit),'Credit limit':amt(a.limit),'Current balance':amt(a.balance),'Overdue':amt(a.overdue),'EMI / reported payment':amt(a.emi),'Annual rate':a.rate===null?'Not reported':a.rate+'%','Tenure':val(a.tenure),'Last payment':val(a.lastPayment),'Written off':amt(a.writtenOff),'Settlement':amt(a.settlement),'Facility status':val(a.facility),'Max numeric DPD':a.maxDPD}).map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div><div class="notice">${a.flags.length?esc(a.flags.join(' · ')):'No account-level flags extracted.'} Verify amounts and status against the original. An EMI / payment amount may be a bullet payment, depending on the report.</div><div class="row"><h3>All extracted payment history (${a.history.length} months)</h3><button id="exportHistory" class="secondary">↓ Export history</button></div><div class="history-chips">${a.history.map(h=>`<div><small>${h.month}</small><span class="dpd ${h.status}">${esc(h.code)}</span></div>`).join('')||'<p>No history codes were reliably extracted.</p>'}</div><details><summary>Review original extracted account text</summary><pre class="source-text">${esc(a.raw)}</pre></details><button id="viewSource" class="secondary" style="margin-top:18px">Open original PDF at page ${a.page} ↗</button>`;$('#closeDetail').onclick=()=>d.close();$('#exportHistory').onclick=()=>download('account-payment-history.csv',[['Account','Month','Code','Classification'],...a.history.map(h=>[a.masked,h.month,h.code,h.status])]);$('#viewSource').onclick=()=>{let f=reportFiles.get(credit);if(!f)return toast('The original file is not available for demonstration data.');if(!f.url)f.url=URL.createObjectURL(f.file);window.open(f.url+'#page='+a.page,'_blank','noopener')};d.showModal()}
function openUpload(){if(busy)return toast('An import is already running.');$('#uploadDialog').showModal()}
async function ocrWorker(log){if(!window.Tesseract)await new Promise((resolve,reject)=>{let s=document.createElement('script');s.src='./ocr/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('OCR engine could not load.'));document.head.appendChild(s)});return await window.Tesseract.createWorker('eng',1,{workerPath:new URL('./ocr/worker.min.js',location.href).href,corePath:new URL('./ocr/tesseract-core-lstm.wasm.js',location.href).href,langPath:new URL('./ocr/',location.href).href,gzip:false,workerBlobURL:false,logger:m=>{if(m.status==='recognizing text')log(`Scanning page… ${Math.round(m.progress*100)}%`)}})}
async function extractPDF(file,log){let task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),useSystemFonts:true});task.onPassword=(cb,reason)=>{let pass=prompt(reason===2?'Incorrect PDF password. Try again:':'Enter this PDF’s password (used locally only):');if(pass===null){task.destroy();return}cb(pass)};let pdf=await task.promise,pages=[],worker=null;try{for(let i=1;i<=pdf.numPages;i++){if(abortScan)throw Error('Import cancelled.');log(`Reading page ${i} of ${pdf.numPages}…`);let p=await pdf.getPage(i),tc=await p.getTextContent(),text=layoutItems(tc.items),ocr=false;if(forceOCR||text.replace(/\s/g,'').length<35){log(`Scanning image page ${i} of ${pdf.numPages}…`);worker??=await ocrWorker(m=>log(`Page ${i}/${pdf.numPages} · ${m}`));let vp=p.getViewport({scale:1.7}),canvas=document.createElement('canvas');canvas.width=vp.width;canvas.height=vp.height;await p.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;await worker.setParameters({preserve_interword_spaces:'1'});let result=await worker.recognize(canvas);text=result.data.text;ocr=true;canvas.width=0;canvas.height=0}pages.push({text,ocr});p.cleanup();await new Promise(r=>setTimeout(r,0))}return pages}finally{if(worker)await worker.terminate();await pdf.destroy()}}
async function queueReports(files){files=Array.from(files||[]).filter(Boolean);if(!files.length)return;if(busy)return toast('Wait for the current import to finish.');busy=true;abortScan=false;$('#importErrors').textContent='';$('#uploadDialog').showModal();$('#cancelImport').hidden=false;$('#uploadClose').disabled=true;let log=s=>{$('#importProgress').textContent=s};let loaded=0;try{for(let file of files){if(abortScan)break;try{let ext=file.name.split('.').pop().toLowerCase();log(`Opening ${file.name}…`);let pages;if(ext==='pdf')pages=await extractPDF(file,log);else if(['png','jpg','jpeg','webp'].includes(ext)){let worker=await ocrWorker(log);try{let res=await worker.recognize(file);pages=[{text:res.data.text,ocr:true}]}finally{await worker.terminate()}}else if(ext==='txt')pages=(await file.text()).split('\f').map(text=>({text,ocr:false}));else throw Error('Use a PDF, TXT, PNG, JPEG or WebP file.');if(!pages.some(p=>p.text.trim().length>10))throw Error('No readable report text was found, even after scanning.');let r=parseCredit(pages,file.name);reports.push(r);reportFiles.set(r,{file});credit=r;creditName=file.name;demo=false;loaded++;render();log(`Read all ${pages.length} pages. ${r.accounts.length} accounts extracted.`)}catch(e){log(`${file.name}: ${e.message||'Could not read this report.'}`);if(files.length>1){let item=document.createElement('p');item.textContent=$('#importProgress').textContent;$('#importErrors').appendChild(item)}if(abortScan)break}}}finally{busy=false;$('#cancelImport').hidden=true;$('#uploadClose').disabled=false;$('#reportInput').value='';if(loaded){if(!$('#importErrors').textContent)$('#uploadDialog').close();toast(`Imported ${loaded} report${loaded>1?'s':''}. Verify extracted values against the originals.`)}}}
const balanceMoney=n=>n===null||n===undefined?'—':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
function currentBalances(){return balanceAnalytics(transactions,{...balancePeriod,opening:bankResult?.opening??null})}
function bankAnalyticsUI(){let groups=channelSummary(transactions),b=currentBalances();return `<section class="card balance-panel" style="margin-top:22px"><div class="row"><div><span class="eyebrow">BALANCE ANALYSIS</span><h2>Average bank balance</h2><p>Daily closing balances, including days without transactions.</p></div><button class="secondary" id="exportDailyBalance" ${b.daily.length?'':'disabled'}>↓ Export daily balances</button></div><div class="balance-controls"><label class="field">Period start<input type="date" id="balanceStart" value="${esc(balancePeriod.start||b.start||'')}"></label><label class="field">Period end<input type="date" id="balanceEnd" value="${esc(balancePeriod.end||b.end||'')}"></label><button id="applyBalancePeriod" class="primary">Calculate average</button></div><div class="stats balance-stats">${stat('Average daily closing balance',balanceMoney(b.average),b.average===null?'Complete daily coverage is required':`${b.days} calendar days · inclusive period`,'◷')}${stat('Average transaction-row balance',balanceMoney(b.observedAverage),'Simple mean of available, classified row balances','≈')}${stat('Balance coverage',b.days?`${b.days-b.missing} / ${b.days}`:'—','Days with an available closing balance','▤')}</div>${b.error?`<div class="notice">${esc(b.error)}</div>`:''}<p class="mini">${b.start&&b.end?`Period: ${b.start} to ${b.end}. `:''}By default, the period runs from the first to the last extracted transaction. Set the actual statement dates for a full-period average. The last available closing balance carries forward on non-transaction days. Missing or unreviewed closing balances make the daily average unavailable; they are never treated as zero. Results depend on complete extraction of the statement.${b.invalid?` ${b.invalid} rows have unrecognized dates.`:''}</p><div class="table-wrap"><table><thead><tr><th>MONTH / SELECTED PORTION</th><th>CALENDAR DAYS</th><th>AVAILABLE DAYS</th><th>AVERAGE DAILY BALANCE</th></tr></thead><tbody>${b.monthly.map(m=>`<tr><td>${m.month}</td><td>${m.days}</td><td>${m.days-m.missing} / ${m.days}</td><td>${balanceMoney(m.average)}</td></tr>`).join('')||'<tr><td colspan="4">No daily balance data available.</td></tr>'}</tbody></table></div></section><section class="card payment-channel-panel"><div class="row"><div><span class="eyebrow">PAYMENT CHANNELS</span><h2>Transfers &amp; automated payments</h2><p>Separate sections for NEFT, IMPS, ACH, NACH, ECS and RTGS.</p></div><button class="secondary" id="exportChannels">↓ Export channel summary</button></div><p class="mini">Channels are matched from narration. ACH and NACH are kept separate. Multiple or missing channel labels go to Other. Amount totals exclude rows needing review; return and reversal entries remain visible.</p><div class="channel-grid">${groups.map((g,i)=>`<details class="channel-card channel-${i%4}"><summary><span class="row"><b>${g.channel==='Other'?'Other / unidentified':g.channel}</b><span class="count">${g.count} rows</span></span><span class="channel-totals"><span>Debit <strong>${money(g.debit)}</strong></span><span>Credit <strong>${money(g.credit)}</strong></span></span><span class="mini">${g.review?g.review+' need review':'No unresolved rows'} · Open transactions ↓</span></summary><div class="channel-actions"><button class="secondary" data-export-channel="${g.channel}">↓ Export ${g.channel}</button></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>NARRATION</th><th>DEBIT</th><th>CREDIT</th><th>STATUS</th></tr></thead><tbody>${g.rows.map(t=>`<tr><td>${esc(t.date)}</td><td style="white-space:normal;min-width:180px">${esc(t.description)}</td><td>${t.review?'—':amt(t.debit)}</td><td>${t.review?'—':amt(t.credit)}</td><td>${t.review?'Needs review':'Classified'}</td></tr>`).join('')||'<tr><td colspan="5">No matching transactions.</td></tr>'}</tbody></table></div></details>`).join('')}</div></section>`}
function bindBankAnalytics(){if($('#applyBalancePeriod'))$('#applyBalancePeriod').onclick=()=>{let start=$('#balanceStart').value,end=$('#balanceEnd').value;if(!start||!end||end<start)return toast('Choose a valid start and end date.');balancePeriod={start,end};render()};if($('#exportDailyBalance'))$('#exportDailyBalance').onclick=()=>download('daily-closing-balances.csv',[['Date','Closing balance','Carried forward','Missing balance'],...currentBalances().daily.map(d=>[d.date,d.balance,d.carried,d.balance===null])]);if($('#exportChannels'))$('#exportChannels').onclick=()=>download('payment-channel-summary.csv',[['Channel','Transactions','Needs review','Total debit','Total credit'],...channelSummary(transactions).map(g=>[g.channel,g.count,g.review,g.debit,g.credit])]);document.querySelectorAll('[data-export-channel]').forEach(button=>button.onclick=()=>{let channel=button.dataset.exportChannel;download(channel.toLowerCase()+'-transactions.csv',[['Date','Narration','Debit','Credit','Balance','Needs review'],...transactions.filter(t=>paymentChannel(t.description)===channel).map(t=>[t.date,t.description,t.review?'':t.debit,t.review?'':t.credit,t.balance,t.review])])})}
function bankMappingUI(){if(!bankTable?.length)return '<p>No text table could be detected. Try OCR or add transactions from the original.</p>';let cfg=bankResult.config||suggestMapping(bankTable),selected=cfg.header??0,headers=bankTable[selected]||[],count=Math.min(Math.max(...bankTable.slice(0,100).map(r=>r.length)),20);return `<div class="mapping-grid"><label class="field">Header row<select id="bankHeader">${bankTable.slice(0,80).map((r,i)=>`<option value="${i}" ${i===selected?'selected':''}>${i+1}: ${esc(r.join(' | ').slice(0,100))}</option>`).join('')}</select></label>${Object.entries({date:'Date',description:'Narration',debit:'Debit / withdrawal',credit:'Credit / deposit',amount:'Single amount',direction:'CR/DR or type',balance:'Running balance'}).map(([k,v])=>`<label class="field">${v}<select data-map="${k}"><option value="-1">Not present</option>${Array.from({length:count},(_,i)=>`<option value="${i}" ${cfg.mapping?.[k]===i?'selected':''}>${i+1}: ${esc(headers[i]||'Column '+(i+1))}</option>`).join('')}</select></label>`).join('')}</div><button id="applyBankMap" class="primary">Apply column mapping</button><p class="mini">For PDFs, mapping uses the extracted columns separated by spaces. If the PDF lost its column structure, scan with OCR and review uncertain rows.</p><div class="table-wrap"><table><tbody>${bankTable.slice(selected,selected+6).map(r=>`<tr>${r.slice(0,20).map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function bindBankUI(){bindBankAnalytics();if($('#bankForceOCR'))$('#bankForceOCR').onchange=e=>forceOCR=e.target.checked;if($('#bankHeader'))$('#bankHeader').onchange=e=>{bankResult.config={header:+e.target.value,mapping:{}};render()};if($('#applyBankMap'))$('#applyBankMap').onclick=()=>{let mapping={};document.querySelectorAll('[data-map]').forEach(s=>mapping[s.dataset.map]=+s.value);if(mapping.date<0||(mapping.amount<0&&mapping.debit<0&&mapping.credit<0))return toast('Map the date and at least one amount column.');bankResult=parseStatementCSV(bankTable,{header:+$('#bankHeader').value,mapping});transactions=bankResult.rows;render();toast(`Column mapping applied: ${transactions.length} rows.`)};if($('#addBankRow'))$('#addBankRow').onclick=()=>editBankRow(-1);if($('#openBankOriginal'))$('#openBankOriginal').onclick=()=>{if(bankFile){let url=URL.createObjectURL(bankFile);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}}}
function editBankRow(i){let t=transactions[i]||{date:'',description:'',amount:0,balance:null,review:true},dialog=$('#bankEditDialog');$('#bankEditContent').innerHTML=`<div class="row"><h2>${i<0?'Add transaction':'Review transaction'}</h2><button class="secondary" id="closeBankEdit">✕ Close</button></div><p>${esc(t.reason||'Enter the values from your original statement.')}</p><div class="mapping-grid"><label class="field">Date<input id="editBankDate" value="${esc(t.date)}" placeholder="DD/MM/YYYY"></label><label class="field">Amount (₹)<input id="editBankAmount" type="number" min="0.01" step="0.01" value="${t.amount||t.debit||t.credit||''}"></label><label class="field">Direction<select id="editBankDirection"><option value="">Choose direction</option><option value="debit" ${!t.review&&t.debit?'selected':''}>Debit / money out</option><option value="credit" ${!t.review&&t.credit?'selected':''}>Credit / money in</option></select></label><label class="field">Balance (optional)<input id="editBankBalance" type="number" step="0.01" value="${t.balance??''}"></label></div><label class="field">Narration<input id="editBankDescription" value="${esc(t.description)}"></label><details><summary>Extracted source row</summary><pre class="source-text">${esc(t.raw||'Manually added row')}</pre></details><button class="primary" id="saveBankEdit" style="margin-top:20px">Save verified transaction</button>`;$('#closeBankEdit').onclick=()=>dialog.close();$('#saveBankEdit').onclick=()=>{let date=$('#editBankDate').value.trim(),amount=+$('#editBankAmount').value,direction=$('#editBankDirection').value,description=$('#editBankDescription').value.trim();if(!date||!description||!(amount>0)||!direction)return toast('Enter date, narration, positive amount and direction.');let row=classifyBank({...t,date,description,amount,balance:$('#editBankBalance').value===''?null:+$('#editBankBalance').value,debit:direction==='debit'?amount:0,credit:direction==='credit'?amount:0,review:false,reason:'Verified manually against the source'});if(i<0)transactions.push(row);else transactions[i]=row;dialog.close();render()};dialog.showModal()}
$('#demo').onclick=()=>{let a=[{lender:'HDFC Bank',type:'Credit Card',balance:42000,overdue:0,limit:220000,status:'Active',active:true},{lender:'Bajaj Finance',type:'Personal Loan',balance:186500,overdue:8500,limit:null,status:'Active',active:true},{lender:'ICICI Bank',type:'Home Loan',balance:1840000,overdue:0,limit:null,status:'Active',active:true},{lender:'Axis Bank',type:'Credit Card',balance:0,overdue:0,limit:150000,status:'Closed',active:false}].map((a,i)=>({...a,id:i+1,masked:'•••• '+[4821,9012,3356,7810][i],page:i+1,ownership:'Individual',opened:'01/01/2022',closed:i===3?'01/02/2026':null,reported:'01/10/2026',sanctioned:null,highCredit:null,emi:null,rate:null,tenure:null,lastPayment:null,writtenOff:null,settlement:null,facility:null,flags:i===1?['Overdue','Late payment']:i===3?['Late payment']:[],maxDPD:i===1?60:i===3?90:0,raw:'ILLUSTRATIVE SAMPLE DATA — not an uploaded customer report.',history:Array.from({length:12},(_,j)=>{let d=new Date(2025,10+j,1,12);let code=i===1&&j%4===1?'030':i===3&&j<3?'090':'000';return{month:d.toISOString().slice(0,7),code,status:code==='000'?'ok':'late'}})}));credit={name:'Sample credit report',demo:true,bureau:'TransUnion CIBIL',pages:12,score:724,scores:[{label:'Sample score',value:724}],customer:{name:'Sample Borrower',dob:null,pan:'•••• 123A',phone:'•••• 4567',email:'s•••@example.com',reportDate:'06/10/2026'},accounts:a,enquiries:[],summary:{reportedBalance:2068500,reportedOverdue:8500,reportedTotal:4,reportedEnquiries:null},totals:{balance:2068500,overdue:8500,active:3,closed:1,util:11.4,secured:1,unsecured:3},warnings:[],signals:[],fields:{},chars:0};reports.push(credit);creditName=credit.name;demo=true;render();toast('Illustrative sample data loaded.')};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#theme').onclick=()=>$('#appearanceDialog').showModal();$('#uploadTop').onclick=()=>page==='bank'?$('#file-bank').click():openUpload();$('#uploadClose').onclick=()=>$('#uploadDialog').close();$('#uploadDialog').addEventListener('cancel',e=>{if(busy){e.preventDefault();abortScan=true;$('#importProgress').textContent='Cancelling after the current page…'}});$('#cancelImport').onclick=()=>{abortScan=true;$('#importProgress').textContent='Cancelling after the current page…'};$('#reportInput').onchange=e=>queueReports(e.target.files);$('#ocrMode').onchange=e=>forceOCR=e.target.value==='force';$('#reportDrop').ondragover=e=>e.preventDefault();$('#reportDrop').ondrop=e=>{e.preventDefault();queueReports(e.dataTransfer.files)};render();

const palettes={prism:{name:'Prism',colors:['#7353bd','#008c8a','#d56b50','#b38919']},burgundy:{name:'Burgundy Aurora',colors:['#95274f','#2a8e93','#c77c2b','#8056bf']},ocean:{name:'Ocean Bloom',colors:['#276bb0','#008c83','#b6508a','#bc8621']},sunset:{name:'Sunset Citrus',colors:['#b54a35','#9b6c17','#488769','#865caa']},forest:{name:'Forest Jewel',colors:['#27765c','#5368b7','#ad527d','#ae8120']}};let appearance={palette:'prism',mode:'light'};try{let saved=JSON.parse((localStorage.getItem('creditlens-appearance')||localStorage.getItem('credora-appearance'))||'null');if(saved&&palettes[saved.palette]&&['light','dark','auto'].includes(saved.mode))appearance=saved}catch{}function applyAppearance(){let p=palettes[appearance.palette];p.colors.forEach((c,i)=>document.body.style.setProperty('--c'+(i+1),c));document.body.dataset.palette=appearance.palette;document.body.classList.toggle('dark',appearance.mode==='dark'||appearance.mode==='auto'&&matchMedia('(prefers-color-scheme: dark)').matches);document.querySelectorAll('[data-palette-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.paletteChoice===appearance.palette)));$('#displayMode').value=appearance.mode;try{localStorage.setItem('creditlens-appearance',JSON.stringify(appearance))}catch{}}$('#paletteChoices').innerHTML=Object.entries(palettes).map(([key,p])=>`<button class="palette-option" data-palette-choice="${key}" aria-pressed="false"><span class="swatches">${p.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span><b>${p.name}</b><small>Coordinated colors for the entire workspace</small></button>`).join('');document.querySelectorAll('[data-palette-choice]').forEach(b=>b.onclick=()=>{appearance.palette=b.dataset.paletteChoice;applyAppearance()});$('#displayMode').onchange=e=>{appearance.mode=e.target.value;applyAppearance()};$('#closeAppearance').onclick=()=>$('#appearanceDialog').close();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(appearance.mode==='auto')applyAppearance()});applyAppearance();
